import{_ as e,o as r,c as d,ag as n}from"./chunks/framework.CD3EN-rd.js";const b=JSON.parse('{"title":"第1章 建设工程基本法律知识","description":"","frontmatter":{"title":"第1章 建设工程基本法律知识","layout":"doc","order":3},"headers":[],"relativePath":"考试/一级建造师/工程法规/第1章 建设工程项目组织、规划与控制.md","filePath":"考试/一级建造师/工程法规/第1章 建设工程项目组织、规划与控制.md","lastUpdated":1772211046000}'),a={name:"考试/一级建造师/工程法规/第1章 建设工程项目组织、规划与控制.md"};function l(s,t,o,g,_,i){return r(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="第1章-建设工程基本法律知识" tabindex="-1">第1章 建设工程基本法律知识 <a class="header-anchor" href="#第1章-建设工程基本法律知识" aria-label="Permalink to &quot;第1章 建设工程基本法律知识&quot;">​</a></h1><h2 id="_1-1-建设工程法律基础" tabindex="-1">1.1 建设工程法律基础 <a class="header-anchor" href="#_1-1-建设工程法律基础" aria-label="Permalink to &quot;1.1  建设工程法律基础&quot;">​</a></h2><p><strong>考点一：法律部门和法律体系★★</strong></p><table><tbody><tr><td><strong>法律体系</strong></td><td colspan="3">通常指由一个国家现行的各个部门法构成的有机联系的统一整体。</td></tr><tr><td rowspan="7">法律部门</td><td>1. 宪法及相关法</td><td>根本大法</td><td>《国籍法》《国务院组织法》《民族区域自治法》</td></tr><tr><td>2. 民商法<br><small>（民 – 民）</small></td><td>平等主体<br>商事活动</td><td>《民法典》《商标法》《专利法》<br>《著作权法》《公司法》<br>《招标投标法》</td></tr><tr><td>3. 行政法<br><small>（官 – 民）</small></td><td>行政监督</td><td>《土地管理法》<br>《城市房地产管理法》<br>《行政处罚法》《行政许可法》《城乡规划法》</td></tr><tr><td>4. 经济法</td><td>协调、干预<br>经济运行</td><td><strong style="color:red;">《统计法》《标准化法》<br>《税收征收管理法》《预算法》《审计法》《反垄断法》</strong></td></tr><tr><td>5. 社会法</td><td>劳动关系、社会<br>保障和社会福利</td><td>《无障碍环境建设法》《残疾人保障法》《矿山安全法》<br>《劳动法》《职业病防治法》《劳动合同法》</td></tr><tr><td>6. 刑法</td><td>犯罪</td><td>《刑法》</td></tr><tr><td>7. 诉讼与非诉讼程序法</td><td>诉讼程序</td><td>《刑事诉讼法》《行政诉讼法》《民事诉讼法》</td></tr></tbody></table><p><strong>坑点提示</strong>：《行政诉讼法》不是行政法；《刑事诉讼法》不是刑法。</p><p><strong>考点二：法的形式★★★</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">法的形式</th><th style="text-align:center;">制订机关</th></tr></thead><tbody><tr><td style="text-align:center;">宪<strong>法</strong></td><td style="text-align:center;">全国人大</td></tr><tr><td style="text-align:center;"><strong>法</strong>律</td><td style="text-align:center;">全国人大及常委会</td></tr><tr><td style="text-align:center;">行政<strong>法规</strong></td><td style="text-align:center;">国务院</td></tr><tr><td style="text-align:center;">地方<strong>法规</strong>（自治条例、单行条例）</td><td style="text-align:center;">省级、设区的市级人大及常委会（自治州、自治县）</td></tr><tr><td style="text-align:center;">部门<strong>规章</strong></td><td style="text-align:center;">国务院各部委</td></tr><tr><td style="text-align:center;">地方政府<strong>规章</strong></td><td style="text-align:center;">省级、设区的市级政府</td></tr><tr><td style="text-align:center;">国际条约</td><td style="text-align:center;">—（世界贸易组织）</td></tr></tbody></table><p>33333</p>',8)])])}const p=e(a,[["render",l]]);export{b as __pageData,p as default};
